  'landing.hero.eyebrow': 'Private beta · recruiters and candidates, one platform',
  'landing.hero.titleLine1': 'Score the pile.',
  'landing.hero.titleLine2': 'Interview the shortlist.',
  'landing.hero.subtitleText': 'Candway turns applicant flow into a defense against random screening. Define one rubric per role, score every CV on evidence, run structured AI interviews, and send shortlists managers actually trust.',
  'landing.hero.btnPrimary': 'Join recruiter beta',
  'landing.hero.btnSecondary': 'Try product demo',
  'landing.hero.trustNote': '✓ Free candidate portal · ✓ Evidence-based rubrics · ✓ No auto-interviews',

  'landing.outcomes.c1_label': 'CVs in',
  'landing.outcomes.c1_hint': 'public apply or bulk upload',
  'landing.outcomes.c2_label': 'role rubric',
  'landing.outcomes.c2_hint': 'the same criteria for everyone',
  'landing.outcomes.c3_label': 'names out',
  'landing.outcomes.c3_hint': 'a shortlist you can defend',

  'landing.pain.eyebrow': 'THE SCREENING PROBLEM',
  'landing.pain.title': 'Traditional recruiting is buried in noise and guesswork.',
  'landing.pain.p1_title': 'The pile',
  'landing.pain.p1_body': 'CVs land in inboxes, shared drives, and three tools. Nobody scores them the same way.',
  'landing.pain.p2_title': 'The guess',
  'landing.pain.p2_body': 'Screening calls go to whoever looks familiar. Stronger profiles never leave the stack.',
  'landing.pain.p3_title': 'The black hole',
  'landing.pain.p3_body': 'Candidates apply and hear nothing. Interviews start with no shared evidence.',

  'landing.tour.s1_title': 'Score every CV against the role',
  'landing.tour.s1_body': 'Public applications and bulk uploads land in the same campaign. Candway reads each CV against your rubric and ranks the pile by evidence — not keywords.',
  'landing.tour.s2_title': 'You choose who gets interviewed',
  'landing.tour.s2_body': 'Interviews stay locked until you send an invite. Candidates can never start one on their own.',
  'landing.tour.s3_title': 'Collect evidence, not vibes',
  'landing.tour.s3_body': 'Invited candidates complete a structured AI interview. Candway maps answers back to the same rubric so the interview can be compared, not just replayed.',
  'landing.tour.s4_title': 'Give candidates a real status',
  'landing.tour.s4_body': 'Applicants see the job, their match, and whether an invite has arrived — no ghosting, no mystery portal.',
  'landing.tour.s5_title': 'Leave with a shortlist you can send',
  'landing.tour.s5_body': 'The campaign ends in a recruiter report: ranked names, rubric evidence, interview notes. Ready for a hiring manager, a client, or a debrief.',

  'landing.faq.q1_title': 'How does Candway score CVs without bias?',
  'landing.faq.q1_body': 'Candway parses CVs against a weighted skill rubric defined per role. Matches are computed based on demonstrated evidence, experience markers, and skill coverage — not keyword tricks.',
  'landing.faq.q2_title': 'Can candidates start AI interviews automatically?',
  'landing.faq.q2_body': 'No. AI interviews remain locked until a recruiter manually sends an invitation. Candidates can track their CV match score in their portal anytime.',
  'landing.faq.q3_title': 'Is Candway free for candidates?',
  'landing.faq.q3_body': 'Yes. Candidate features — CV Builder, application tracking, and interview practice — are 100% free with no credit card required.',
  'landing.faq.q4_title': 'How does Candway support Tunisian & global hiring?',
  'landing.faq.q4_body': 'Candway supports local Tunisian TND benchmarks, multi-currency salary estimates, French/English/Arabic language options, and MENA/European remote roles.',

