  'landing.hero.eyebrow': 'Bêta privée · recruteurs et candidats, une seule plateforme',
  'landing.hero.titleLine1': 'Scorez la pile.',
  'landing.hero.titleLine2': 'Entretiennez la shortlist.',
  'landing.hero.subtitleText': 'Candway transforme le flux de candidatures en rempart contre le tri aléatoire. Définissez une grille par poste, notez chaque CV sur des preuves, menez des entretiens IA structurés et envoyez des shortlists que les managers approuvent.',
  'landing.hero.btnPrimary': 'Rejoindre la bêta recruteur',
  'landing.hero.btnSecondary': 'Essayer la démo produit',
  'landing.hero.trustNote': '✓ Portail candidat gratuit · ✓ Grilles basées sur des preuves · ✓ Pas d\'entretiens automatiques',

  'landing.outcomes.c1_label': 'CV entrants',
  'landing.outcomes.c1_hint': 'candidature publique ou import en masse',
  'landing.outcomes.c2_label': 'grille du poste',
  'landing.outcomes.c2_hint': 'les mêmes critères pour tous',
  'landing.outcomes.c3_label': 'noms retenus',
  'landing.outcomes.c3_hint': 'une shortlist que vous pouvez défendre',

  'landing.pain.eyebrow': 'LE PROBLÈME DU TRI',
  'landing.pain.title': 'Le recrutement traditionnel est noyé dans le bruit et les suppositions.',
  'landing.pain.p1_title': 'La pile',
  'landing.pain.p1_body': 'Les CV atterrissent dans les boîtes mail, les disques partagés et trois outils. Personne ne les note de la même façon.',
  'landing.pain.p2_title': 'Le pari',
  'landing.pain.p2_body': 'Les appels de présélection vont à ceux qui semblent familiers. Les meilleurs profils restent dans la pile.',
  'landing.pain.p3_title': 'Le trou noir',
  'landing.pain.p3_body': 'Les candidats postulent et n\'ont aucune nouvelle. Les entretiens démarrent sans preuves partagées.',

  'landing.tour.s1_title': 'Notez chaque CV face au poste',
  'landing.tour.s1_body': 'Les candidatures publiques et les imports en masse arrivent dans la même campagne. Candway lit chaque CV face à votre grille et classe la pile selon les preuves — pas les mots-clés.',
  'landing.tour.s2_title': 'Vous choisissez qui est interviewé',
  'landing.tour.s2_body': 'Les entretiens restent verrouillés jusqu\'à ce que vous envoyiez une invitation. Les candidats ne peuvent jamais en lancer un d\'eux-mêmes.',
  'landing.tour.s3_title': 'Collectez des preuves, pas des impressions',
  'landing.tour.s3_body': 'Les candidats invités passent un entretien IA structuré. Candway relie les réponses à la même grille pour que l\'entretien puisse être comparé, pas seulement rejoué.',
  'landing.tour.s4_title': 'Donnez aux candidats un vrai statut',
  'landing.tour.s4_body': 'Les candidats voient le poste, leur correspondance et si une invitation est arrivée — pas de silence, pas de portail mystère.',
  'landing.tour.s5_title': 'Repartez avec une shortlist prête à envoyer',
  'landing.tour.s5_body': 'La campagne se termine par un rapport recruteur : noms classés, preuves de la grille, notes d\'entretien. Prêt pour un responsable du recrutement, un client ou un débriefing.',

  'landing.faq.q1_title': 'Comment Candway note-t-il les CV sans biais ?',
  'landing.faq.q1_body': 'Candway analyse les CV à l\'aide d\'une grille de compétences pondérée définie par poste. La correspondance est calculée à partir de preuves démontrées, de marqueurs d\'expérience et de la couverture des compétences — pas d\'astuces de mots-clés.',
  'landing.faq.q2_title': 'Les candidats peuvent-ils lancer des entretiens IA automatiquement ?',
  'landing.faq.q2_body': 'Non. Les entretiens IA restent verrouillés jusqu\'à ce qu\'un recruteur envoie manuellement une invitation. Les candidats peuvent suivre leur score de correspondance CV à tout moment dans leur portail.',
  'landing.faq.q3_title': 'Candway est-il gratuit pour les candidats ?',
  'landing.faq.q3_body': 'Oui. Les fonctionnalités candidat — Générateur de CV, suivi des candidatures et entraînement aux entretiens — sont 100 % gratuites, sans carte bancaire.',
  'landing.faq.q4_title': 'Comment Candway soutient-il le recrutement tunisien et international ?',
  'landing.faq.q4_body': 'Candway prend en charge les références locales en TND, les estimations de salaires multi-devises, les options de langue français/anglais/arabe et les postes à distance MENA/Europe.',

